mapper.sql:
select em.target_user_id as "targetId", em.evaluation_year as "evaluationYear", min(em.area_code) as "areaCode", coalesce(max(org.organization_name), '-') as "organizationName", coalesce(max(kps.name), max(u.login_id), concat('사용자 ', em.target_user_id)) as "targetName", coalesce(max(fec.confirmation_status), case when bool_and(em.material_status = '평가확정') then '평가확정' else '인증' end) as "confirmationStatus", max(fec.confirmed_by) as "confirmedBy", coalesce(max(confirm_kps.name), max(confirm_user.login_id)) as "confirmedByName", to_char(max(fec.confirmed_at), 'YYYY-MM-DD"T"HH24:MI:SS') as "confirmedAt", max(fec.canceled_by) as "canceledBy", coalesce(max(cancel_kps.name), max(cancel_user.login_id)) as "canceledByName", to_char(max(fec.canceled_at), 'YYYY-MM-DD"T"HH24:MI:SS') as "canceledAt", max(fec.cancel_reason) as "cancelReason", count(em.evaluation_material_id)::integer as "materialCount", coalesce(sum(em.calculated_score), 0)::numeric(10,2) as "totalScore" from evaluation_materials em join users u on u.user_id = em.target_user_id left join korus_personnel_snapshots kps on kps.employee_no = u.employee_no left join organizations org on org.organization_code = kps.organization_code left join final_evaluation_confirmations fec on fec.target_user_id = em.target_user_id and fec.evaluation_year = em.evaluation_year left join users confirm_user on confirm_user.user_id = fec.confirmed_by left join korus_personnel_snapshots confirm_kps on confirm_kps.employee_no = confirm_user.employee_no left join users cancel_user on cancel_user.user_id = fec.canceled_by left join korus_personnel_snapshots cancel_kps on cancel_kps.employee_no = cancel_user.employee_no where em.deleted_yn = 'N' and em.material_status in ('인증','평가확정')
and em.evaluation_year = #{criteria.normalizedEvaluationYear}
and em.area_code = #{criteria.normalizedAreaCode}
and em.target_user_id = #{criteria.normalizedTargetUserId}
group by em.target_user_id, em.evaluation_year
having coalesce(max(fec.confirmation_status), case when bool_and(em.material_status = '평가확정') then '평가확정' else '인증' end) = #{criteria.normalizedConfirmationStatus}

mapper.select:
select count(*)
from evaluation_materials em
where em.target_user_id = #{targetId}
  and em.evaluation_year = #{evaluationYear}
  and em.deleted_yn = 'N'
  and em.material_status = '평가확정'

mapper.update:
update evaluation_materials
set material_status = #{nextStatus},
    request_id = #{requestId},
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{requestUserId}
where target_user_id = #{targetId}
  and evaluation_year = #{evaluationYear}
  and deleted_yn = 'N'
  and material_status = #{previousStatus}

mapper.insert:
insert into data_change_histories (target_business, target_key, change_type, field_name, before_value, after_value, changed_by, change_reason)
select 'BASIC45_EVALUATION_MATERIAL',
       concat('evaluation_material_id:', em.evaluation_material_id),
       'UPDATE',
       'material_status',
       #{previousStatus},
       #{nextStatus},
       #{requestUserId},
       #{changeReason}
from evaluation_materials em
where em.target_user_id = #{targetId}
  and em.evaluation_year = #{evaluationYear}
  and em.deleted_yn = 'N'
  and em.material_status = #{nextStatus}
  and em.request_id = #{requestId}
